import {
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec4,
  mix,
  smoothstep,
  color,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    CylinderGeometry,
    OctahedronGeometry,
    PlaneGeometry,
    DirectionalLight,
    PointLight,
    AmbientLight,
    Color,
    DoubleSide,
  } = THREE;

  const group = new Group();
  group.name = 'glass-prism-node';

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.6, hex: '#12121a' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---------- STAGE BACKDROP ----------
  const gStops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 1, hex: colors.ink },
  ];
  const cBottom = new Color(gStops[0].hex);
  const cMid = new Color(gStops[Math.min(1, gStops.length - 1)].hex);
  const cTop = new Color(gStops[gStops.length - 1].hex);

  const bgMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    const lower = mix(vec3(cBottom.r, cBottom.g, cBottom.b), vec3(cMid.r, cMid.g, cMid.b), smoothstep(0.0, 0.6, v));
    const upper = mix(lower, vec3(cTop.r, cTop.g, cTop.b), smoothstep(0.6, 1.0, v));
    bgMat.colorNode = vec4(upper, float(1.0));
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), bgMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdrop.geometry, bgMat);

  // ---------- LIGHTS (node-local rim + accent) ----------
  const ambient = new AmbientLight(0xffffff, 0.35);
  group.add(ambient);

  // cool back rim from behind-left
  const rim = new DirectionalLight(0x9fb0c4, 1.4);
  rim.position.set(-3.2, 1.4, -3.0);
  rim.target.position.set(0, 0, 0);
  group.add(rim);
  group.add(rim.target);

  // subtle key
  const key = new DirectionalLight(0xe8ecf2, 1.1);
  key.position.set(2.6, 3.0, 3.2);
  key.target.position.set(0, 0, 0);
  group.add(key);
  group.add(key.target);

  // accent point light from the emissive core
  const accentColor = new Color(colors.accent);
  const coreLight = new PointLight(colors.accent, 1.2, 6, 2);
  coreLight.position.set(0, 0, 0);
  group.add(coreLight);

  // ---------- PRISM ASSEMBLY ----------
  const prism = new Group();
  prism.name = 'prism';
  group.add(prism);

  // triangular prism via 3-sided cylinder (equilateral cross-section)
  // side length 1.2 -> circumradius = 1.2 / sqrt(3)
  const radius = 1.2 / Math.sqrt(3);
  const prismGeo = new CylinderGeometry(radius, radius, 1.8, 3, 1, false);

  const glassMat = new MeshPhysicalNodeMaterial();
  glassMat.transmission = 1.0;
  glassMat.thickness = 0.9;
  glassMat.ior = 1.55;
  glassMat.roughness = 0.08;
  glassMat.metalness = 0.0;
  glassMat.clearcoat = 0.25;
  glassMat.clearcoatRoughness = 0.1;
  glassMat.iridescence = 1.0;
  glassMat.iridescenceIOR = 1.3;
  glassMat.iridescenceThicknessRange = [120, 480];
  glassMat.attenuationColor = new Color(colors.paper);
  glassMat.attenuationDistance = 2.5;
  glassMat.transparent = true;
  glassMat.side = DoubleSide;
  // faint dispersion-tinted base color node so edges carry chroma
  {
    const v = uv();
    const disp = mix(
      vec3(accentColor.r, accentColor.g, accentColor.b),
      vec3(0.62, 0.69, 0.77),
      smoothstep(0.0, 1.0, v.x)
    );
    glassMat.colorNode = vec4(mix(vec3(1.0, 1.0, 1.0), disp, float(0.18)), float(1.0));
  }

  const prismMesh = new Mesh(prismGeo, glassMat);
  // axis horizontal: cylinder axis is Y by default -> rotate to lay along X
  prismMesh.rotation.z = Math.PI / 2;
  prism.add(prismMesh);
  disposables.push(prismGeo, glassMat);

  // spec orientation: 12deg on z, 20deg on y applied to the assembly
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);

  // ---------- EMISSIVE CORE ----------
  const coreGeo = new OctahedronGeometry(0.35, 0);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new Color(colors.accent);
  coreMat.emissive = new Color(colors.accent);
  coreMat.emissiveIntensity = 2.2;
  coreMat.roughness = 0.5;
  coreMat.metalness = 0.0;
  const coreMesh = new Mesh(coreGeo, coreMat);
  prism.add(coreMesh);
  disposables.push(coreGeo, coreMat);

  // ---------- CAUSTIC STREAK ON FLOOR ----------
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial();
  causticMat.transparent = true;
  {
    const x = uv().x;
    const cA = accentColor;
    const cB = new Color(colors.paper);
    const cC = new Color('#9fb0c4');
    const seg1 = mix(vec3(cA.r, cA.g, cA.b), vec3(cB.r, cB.g, cB.b), smoothstep(0.2, 0.5, x));
    const seg2 = mix(seg1, vec3(cC.r, cC.g, cC.b), smoothstep(0.5, 0.8, x));
    // soft edge falloff along y and ends
    const edge = smoothstep(0.0, 0.35, uv().y).mul(smoothstep(1.0, 0.65, uv().y));
    const ends = smoothstep(0.0, 0.12, x).mul(smoothstep(1.0, 0.88, x));
    causticMat.colorNode = vec4(seg2, float(0.35).mul(edge).mul(ends));
  }
  const caustic = new Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0.2);
  group.add(caustic);
  disposables.push(causticGeo, causticMat);

  // ---------- CONTACT SHADOW ----------
  const shadowGeo = new PlaneGeometry(2.2, 2.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  {
    const d = uv().sub(0.5).length();
    const a = smoothstep(0.5, 0.0, d).mul(float(0.5));
    shadowMat.colorNode = vec4(vec3(0.0, 0.0, 0.0), a);
  }
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.12, 0);
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- TEXT ----------
  const items = config.textContent ?? spec.textContent ?? [];
  let headlineText = 'Light, machined.';
  let captionText = 'SAPPHIRE OVER DIAL / ZERO DISTORTION';
  for (const it of items) {
    if (it.role === 'headline') headlineText = it.text;
    else if (it.role === 'caption') captionText = it.text;
  }

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: -0.3,
  });
  headline.position.set(0, -1.75, 0.2);
  group.add(headline);

  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 18,
    color: '#9fb0c4',
    align: 'center',
    letterSpacingPx: 1.4,
  });
  caption.position.set(0, -2.25, 0.2);
  group.add(caption);

  // ---------- PRIMITIVES ----------
  const primList = config.cinematicPrimitives ?? [];
  for (const p of primList) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const target = p.name === 'depth-rotate' ? prism : group;
      const handle = fn(target, p.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---------- ENTRANCE + IDLE MOTION ----------
  group.position.y += 0.4;
  const tlIntro = gsap.timeline();
  tlIntro.fromTo(
    group.position,
    { y: group.position.y },
    { y: group.position.y - 0.4, duration: 0.7, ease: 'power3.out' }
  );
  tlIntro.fromTo(
    prism.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' },
    0.1
  );
  tlIntro.to(prism.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  timelines.push(tlIntro);

  // slow idle orbit of the core + gentle breathing of prism
  const tlIdle = gsap.timeline({ repeat: -1, yoyo: true });
  tlIdle.to(coreMesh.rotation, { y: Math.PI * 2, duration: 12, ease: 'none' });
  timelines.push(tlIdle);

  const tlBreath = gsap.timeline({ repeat: -1, yoyo: true });
  tlBreath.to(coreMat, { emissiveIntensity: 1.7, duration: 2.4, ease: 'sine.inOut' });
  timelines.push(tlBreath);

  // ---------- HOVER / PRESS HANDLERS ----------
  const baseZ = prism.rotation.z;
  const baseX = prism.rotation.x;
  group.userData.handlers = {
    hover: (hovering) => {
      gsap.to(prism.rotation, {
        z: hovering ? baseZ + THREE.MathUtils.degToRad(6) : baseZ,
        duration: 0.35,
        ease: 'power2.out',
      });
    },
    pointermove: (pointer) => {
      if (!pointer) return;
      const tx = (pointer.y ?? 0) * THREE.MathUtils.degToRad(10);
      const ty = (pointer.x ?? 0) * THREE.MathUtils.degToRad(10);
      gsap.to(prism.rotation, {
        x: baseX + tx,
        duration: 0.35,
        ease: 'power2.out',
      });
      gsap.to(caustic.scale, {
        x: 1 + Math.abs(pointer.x ?? 0) * 0.08,
        duration: 0.35,
        ease: 'power2.out',
      });
    },
    click: () => {
      const tl = gsap.timeline();
      tl.to(prism.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
      tl.to(prism.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
      ctx.emit?.('navigate', { to: 'hub-features' });
    },
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    headline.traverse?.((o) => {
      o.geometry?.dispose?.();
      o.material?.dispose?.();
    });
    caption.traverse?.((o) => {
      o.geometry?.dispose?.();
      o.material?.dispose?.();
    });
  };

  return group;
}
